import os
import json
import hmac
import hashlib
import time
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import secrets

# Role hierarchy
ROLE_GUEST = 0
ROLE_USER = 10
ROLE_MODERATOR = 20
ROLE_ADMIN = 30

# Maximum request body size (bytes) to prevent memory exhaustion
MAX_BODY_SIZE = 64 * 1024

# Session lifetime in seconds
SESSION_TTL = 3600


class PermissionEngine:
    """Calculates effective permissions based on role composition."""

    PERMISSION_MATRIX = {
        'read': ROLE_GUEST,
        'write': ROLE_USER,
        'delete': ROLE_MODERATOR,
        'admin_panel': ROLE_ADMIN,
        'user_management': ROLE_ADMIN,
        'export_data': ROLE_MODERATOR,
        'bulk_operations': ROLE_MODERATOR,
    }

    def __init__(self):
        self._role_adjustments = {}  # user_id -> adjustment
        self._lock = threading.Lock()

    def register_adjustment(self, user_id, adjustment):
        """Register a temporary role adjustment (e.g., for delegated access)."""
        with self._lock:
            self._role_adjustments[user_id] = adjustment

    def clear_adjustment(self, user_id):
        with self._lock:
            self._role_adjustments.pop(user_id, None)

    def compute_effective_role(self, base_role, user_id):
        """Compute effective role level with adjustments.

        Adjustments can be negative (temporary demotion for restricted contexts)
        or positive (temporary elevation for delegated tasks).
        The result is clamped to valid range [0, 30].
        """
        with self._lock:
            adjustment = self._role_adjustments.get(user_id, 0)

        # Calculate effective role with adjustment
        effective = base_role + adjustment

        # Clamp to valid range
        if effective > ROLE_ADMIN:
            effective = ROLE_ADMIN
        if effective < ROLE_GUEST:
            effective = ROLE_GUEST

        return effective

    def check_permission(self, effective_role, permission):
        """Check if effective role level grants the requested permission."""
        required = self.PERMISSION_MATRIX.get(permission)
        if required is None:
            return False
        # Grant access if effective role meets or exceeds requirement
        return effective_role >= required


class SessionStore:
    def __init__(self):
        self._sessions = {}
        self._lock = threading.Lock()

    def create_session(self, user_id, role):
        token = secrets.token_hex(32)
        with self._lock:
            self._sessions[token] = {
                'user_id': user_id,
                'role': role,
                'created_at': time.time()
            }
        return token

    def get_session(self, token):
        with self._lock:
            session = self._sessions.get(token)
            if not session:
                return None
            # Enforce session expiry (CWE-613 fix)
            if time.time() - session['created_at'] > SESSION_TTL:
                self._sessions.pop(token, None)
                return None
            return session

    def invalidate(self, token):
        with self._lock:
            self._sessions.pop(token, None)


class UserDatabase:
    def __init__(self):
        # Require an explicit app secret; do not fall back to a hardcoded key.
        self._app_secret = os.environ.get('APP_SECRET')
        if not self._app_secret:
            raise RuntimeError('APP_SECRET environment variable must be set')
        self._users = {
            'admin': {'password_hash': self._hash_pw(os.environ.get('ADMIN_PW', 'changeme')), 'role': ROLE_ADMIN},
            'moderator': {'password_hash': self._hash_pw(os.environ.get('MOD_PW', 'modpass')), 'role': ROLE_MODERATOR},
            'alice': {'password_hash': self._hash_pw(os.environ.get('ALICE_PW', 'alice123')), 'role': ROLE_USER},
            'guest': {'password_hash': self._hash_pw(os.environ.get('GUEST_PW', 'guest')), 'role': ROLE_GUEST},
        }

    def _hash_pw(self, pw):
        """Hash password with HMAC-SHA256 using app secret as key."""
        key = self._app_secret.encode()
        return hmac.new(key, pw.encode(), hashlib.sha256).hexdigest()

    def verify(self, username, password):
        user = self._users.get(username)
        if not user:
            return None
        expected = user['password_hash']
        provided = self._hash_pw(password)
        if hmac.compare_digest(expected, provided):
            return {'user_id': username, 'role': user['role']}
        return None


class DelegationService:
    """Handles temporary permission delegation between users.

    A higher-privileged user can delegate a subset of their permissions
    to a lower-privileged user for a limited time.
    """

    def __init__(self, permission_engine, session_store):
        self._engine = permission_engine
        self._sessions = session_store
        self._delegations = {}  # target_user -> {grantor, permissions, expires}
        self._lock = threading.Lock()

    def delegate(self, grantor_session, target_user_id, permissions, duration=3600):
        """Delegate permissions from grantor to target user."""
        grantor = self._sessions.get_session(grantor_session)
        if not grantor:
            return {'error': 'invalid session'}

        grantor_role = grantor['role']
        grantor_effective = self._engine.compute_effective_role(grantor_role, grantor['user_id'])

        # Verify grantor has all permissions they're trying to delegate
        for perm in permissions:
            if not self._engine.check_permission(grantor_effective, perm):
                return {'error': f'grantor lacks permission: {perm}'}

        # Calculate the role adjustment needed for target
        # Find the maximum required role among delegated permissions
        max_required = max(
            self._engine.PERMISSION_MATRIX.get(p, 0) for p in permissions
        )

        # SECURITY: Cap delegation - cannot delegate beyond grantor's own level
        if max_required > grantor_effective:
            return {'error': 'cannot delegate beyond own level'}

        with self._lock:
            self._delegations[target_user_id] = {
                'grantor': grantor['user_id'],
                'permissions': permissions,
                'max_required_role': max_required,
                'expires': time.time() + duration
            }

        return {'status': 'delegated', 'target': target_user_id, 'permissions': permissions}

    def apply_delegation(self, user_id, base_role):
        """Apply any active delegation to compute role adjustment.

        SECURITY: Only grants access to specifically delegated permissions,
        not a blanket role elevation. The adjustment is capped to never
        exceed the delegated permission set.
        """
        with self._lock:
            delegation = self._delegations.get(user_id)

        if not delegation:
            return 0, None

        if time.time() > delegation['expires']:
            with self._lock:
                self._delegations.pop(user_id, None)
            return 0, None

        # Return the adjustment AND the allowed permission set
        needed = delegation['max_required_role']
        adjustment = needed - base_role

        # Never allow negative adjustments from delegation (demotion)
        if adjustment < 0:
            adjustment = 0

        return adjustment, set(delegation['permissions'])

    def revoke(self, user_id):
        with self._lock:
            self._delegations.pop(user_id, None)
        self._engine.clear_adjustment(user_id)


class APIHandler(BaseHTTPRequestHandler):
    user_db = None
    session_store = None
    permission_engine = None
    delegation_service = None

    def do_POST(self):
        path = urlparse(self.path).path

        if path == '/login':
            self._handle_login()
        elif path == '/delegate':
            self._handle_delegate()
        elif path == '/action':
            self._handle_action()
        else:
            self._respond(404, {'error': 'not found'})

    def do_GET(self):
        path = urlparse(self.path).path
        if path == '/admin/users':
            self._handle_admin_users()
        else:
            self._respond(404, {'error': 'not found'})

    def _read_body(self):
        try:
            length = int(self.headers.get('Content-Length', 0))
        except (TypeError, ValueError):
            return None
        if length <= 0:
            return {}
        # Cap body size to prevent memory exhaustion (CWE-400 fix)
        if length > MAX_BODY_SIZE:
            return None
        raw = self.rfile.read(length)
        try:
            return json.loads(raw)
        except (json.JSONDecodeError, ValueError):
            return None

    def _get_token(self):
        auth = self.headers.get('Authorization', '')
        if auth.startswith('Bearer '):
            return auth[7:]
        return None

    def _handle_login(self):
        body = self._read_body()
        if body is None:
            self._respond(400, {'error': 'invalid request body'})
            return
        username = body.get('username', '')
        password = body.get('password', '')

        if not username or not password:
            self._respond(400, {'error': 'missing credentials'})
            return

        result = self.user_db.verify(username, password)
        if not result:
            self._respond(401, {'error': 'invalid credentials'})
            return

        token = self.session_store.create_session(result['user_id'], result['role'])
        self._respond(200, {'token': token, 'role': result['role']})

    def _handle_delegate(self):
        token = self._get_token()
        if not token:
            self._respond(401, {'error': 'unauthorized'})
            return

        body = self._read_body()
        if body is None:
            self._respond(400, {'error': 'invalid request body'})
            return
        target = body.get('target_user')
        permissions = body.get('permissions', [])
        duration = body.get('duration', 3600)

        if not target or not permissions:
            self._respond(400, {'error': 'missing target_user or permissions'})
            return

        # Cap duration to 1 hour max
        try:
            duration = min(int(duration), 3600)
        except (TypeError, ValueError):
            self._respond(400, {'error': 'invalid duration'})
            return

        result = self.delegation_service.delegate(token, target, permissions, duration)
        if 'error' in result:
            self._respond(403, result)
        else:
            self._respond(200, result)

    def _handle_action(self):
        token = self._get_token()
        if not token:
            self._respond(401, {'error': 'unauthorized'})
            return

        session = self.session_store.get_session(token)
        if not session:
            self._respond(401, {'error': 'invalid session'})
            return

        body = self._read_body()
        if body is None:
            self._respond(400, {'error': 'invalid request body'})
            return
        action = body.get('action', '')

        if not action:
            self._respond(400, {'error': 'missing action'})
            return

        user_id = session['user_id']
        base_role = session['role']

        # Apply any active delegation - returns adjustment AND allowed permissions
        delegation_adj, allowed_perms = self.delegation_service.apply_delegation(user_id, base_role)

        # If delegation exists, only allow specifically delegated permissions
        if allowed_perms is not None:
            if action not in allowed_perms:
                self._respond(403, {'error': 'action not in delegated permission set'})
                return
            self.permission_engine.register_adjustment(user_id, delegation_adj)

        # Compute effective role and check permission
        effective_role = self.permission_engine.compute_effective_role(base_role, user_id)

        if self.permission_engine.check_permission(effective_role, action):
            self._respond(200, {
                'status': 'allowed',
                'action': action,
                'effective_role': effective_role,
                'user': user_id
            })
        else:
            self._respond(403, {'error': 'insufficient permissions', 'effective_role': effective_role})

        # Clean up adjustment after request
        self.permission_engine.clear_adjustment(user_id)

    def _handle_admin_users(self):
        token = self._get_token()
        if not token:
            self._respond(401, {'error': 'unauthorized'})
            return

        session = self.session_store.get_session(token)
        if not session:
            self._respond(401, {'error': 'invalid session'})
            return

        user_id = session['user_id']
        base_role = session['role']

        # Admin panel requires base admin role - delegations cannot grant admin panel access
        if base_role < ROLE_ADMIN:
            self._respond(403, {'error': 'admin access required - delegation not accepted'})
            return

        # Return user list (without password hashes)
        users = {uid: {'role': info['role']} for uid, info in self.user_db._users.items()}
        self._respond(200, {'users': users})

    def _respond(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def log_message(self, format, *args):
        pass  # Suppress request logging


def create_server(port=8080):
    permission_engine = PermissionEngine()
    session_store = SessionStore()
    user_db = UserDatabase()
    delegation_service = DelegationService(permission_engine, session_store)

    APIHandler.user_db = user_db
    APIHandler.session_store = session_store
    APIHandler.permission_engine = permission_engine
    APIHandler.delegation_service = delegation_service

    server = HTTPServer(('127.0.0.1', port), APIHandler)
    return server


if __name__ == '__main__':
    server = create_server()
    print('Server running on port 8080')
    server.serve_forever()
